"use client"

import * as React from "react"
import { cn } from "cn"

import { Field, FieldError, FieldLabel } from "@tecton/react/components/field"
import { Input } from "@tecton/react/components/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@tecton/react/components/select"
import { Separator } from "@tecton/react/components/separator"
import { Slider } from "@tecton/react/components/slider"
import { ColorSwatch } from "@tecton/react/tecton/color-swatch"
import { useLocale } from "@tecton/react/tecton/provider"

import {
  getPair,
  getSurface,
  lineWidths,
  surfacePairs,
  validateDepths,
  volumes,
} from "../data"
import type { HorizonSettings } from "../data"

const lineWidthItems = lineWidths.map((width) => ({
  value: String(width),
  label: (
    <>
      <span className="font-mono tabular-nums">{width}</span>
      <span className="text-muted-foreground">px</span>
    </>
  ),
}))

type HorizonFormProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  value: HorizonSettings
  onChange: (next: HorizonSettings) => void
}

function HorizonForm({
  className,
  value,
  onChange,
  ...props
}: HorizonFormProps) {
  const pair = getPair(value.pairId)
  const top = getSurface(pair.top)
  const base = getSurface(pair.base)
  const id = React.useId()
  const errorId = `${id}-depth-error`
  const depthError = validateDepths(value)

  const set = <TKey extends keyof HorizonSettings>(
    key: TKey,
    next: HorizonSettings[TKey]
  ) => onChange({ ...value, [key]: next })

  return (
    <div
      data-slot="horizon-form"
      className={cn("flex flex-col gap-4", className)}
      {...props}
    >
      <Field>
        <FieldLabel htmlFor={`${id}-pair`}>Surface pair</FieldLabel>
        <Select
          id={`${id}-pair`}
          value={value.pairId}
          onValueChange={(pairId) => {
            if (pairId === null) return
            const next = getPair(pairId)
            onChange({
              ...value,
              pairId: next.id,
              topDepth: getSurface(next.top).depth,
              bottomDepth: getSurface(next.base).depth,
            })
          }}
          items={surfacePairs.map((item) => ({
            value: item.id,
            label: item.label,
          }))}
        >
          <SelectTrigger variant="filled">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {surfacePairs.map((item) => (
              <SelectItem key={item.id} value={item.id}>
                {item.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </Field>

      <div className="grid grid-cols-2 gap-3">
        <Field>
          <FieldLabel htmlFor={`${id}-volume`}>Volume</FieldLabel>
          <Select
            id={`${id}-volume`}
            value={value.volumeId}
            onValueChange={(volumeId) => {
              if (volumeId !== null) set("volumeId", volumeId)
            }}
            items={volumes.map((item) => ({
              value: item.id,
              label: item.label,
            }))}
          >
            <SelectTrigger variant="filled">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {volumes.map((item) => (
                <SelectItem key={item.id} value={item.id}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
        <Field>
          <FieldLabel htmlFor={`${id}-line`}>Line</FieldLabel>
          <Select
            id={`${id}-line`}
            value={String(value.lineWidth)}
            onValueChange={(width) => {
              if (width !== null) set("lineWidth", Number(width))
            }}
            items={lineWidthItems}
          >
            <SelectTrigger variant="filled">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {lineWidthItems.map((item) => (
                <SelectItem key={item.value} value={item.value}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
      </div>

      <HorizonRow label="Horizon 1" surface={top} />
      <HorizonRow label="Horizon 2" surface={base} />

      <Separator emphasis="subtle" />

      <div className="grid grid-cols-2 gap-3">
        <DepthField
          label="Top depth (TVDSS)"
          value={value.topDepth}
          onValueChange={(next) => set("topDepth", next)}
          errorId={depthError ? errorId : undefined}
        />
        <DepthField
          label="Bottom depth (TVDSS)"
          value={value.bottomDepth}
          onValueChange={(next) => set("bottomDepth", next)}
          errorId={depthError ? errorId : undefined}
        />
        <FieldError id={errorId} className="col-span-2 text-xs">
          {depthError}
        </FieldError>
      </div>

      <LabelledSlider
        label="Opacity"
        value={value.opacity}
        unit="%"
        min={0}
        max={100}
        step={5}
        onValueChange={(next) => set("opacity", next)}
      />
      <LabelledSlider
        label="Smoothing"
        value={value.smoothing}
        unit="m"
        min={0}
        max={100}
        step={5}
        onValueChange={(next) => set("smoothing", next)}
      />
    </div>
  )
}

/** The group and decimal separators of a locale. */
function separators(locale: string) {
  const parts = new Intl.NumberFormat(locale).formatToParts(12345.6)
  return {
    group: parts.find((part) => part.type === "group")?.value ?? ",",
    decimal: parts.find((part) => part.type === "decimal")?.value ?? ".",
  }
}

/** A number typed in a locale's format; `NaN` for an empty or partial entry. */
function parseNumber(text: string, locale: string) {
  const { group, decimal } = separators(locale)
  const normalized = text
    .trim()
    .split(group)
    .join("")
    .replace(/[\s\u00a0\u202f]/g, "")
    .replace(decimal, ".")
  return /^[+-]?(\d+\.?\d*|\.\d+)$/.test(normalized)
    ? Number(normalized)
    : Number.NaN
}

/**
 * A depth in metres: a text field that accepts a partial entry such as "-"
 * while typing and shows the value in the locale's format. The entry is
 * committed on blur or Enter, the arrow keys step it by one metre, and an
 * empty or unparsable entry leaves the previous value in place.
 */
function DepthField({
  label,
  value,
  onValueChange,
  errorId,
}: {
  label: string
  value: number
  onValueChange: (next: number) => void
  /** Id of the error that describes the pair; set while it is invalid. */
  errorId?: string | undefined
}) {
  const id = React.useId()
  const { locale } = useLocale()
  // The text being typed; `null` shows the formatted value.
  const [draft, setDraft] = React.useState<string | null>(null)

  const commit = () => {
    if (draft === null) return
    const next = parseNumber(draft, locale)
    if (!Number.isNaN(next)) onValueChange(next)
    setDraft(null)
  }

  const step = (delta: number) => {
    const current = draft === null ? value : parseNumber(draft, locale)
    onValueChange((Number.isNaN(current) ? value : current) + delta)
    setDraft(null)
  }

  return (
    <Field data-invalid={errorId !== undefined}>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <Input
        id={id}
        variant="filled"
        inputMode="decimal"
        autoComplete="off"
        className="h-8 font-mono text-sm tabular-nums md:text-xs"
        value={draft ?? value.toLocaleString(locale)}
        onChange={(event) => {
          // Only what can become a number: sign, digits and separators.
          if (/^[+-]?[\d\s.,'\u00a0\u202f]*$/.test(event.target.value))
            setDraft(event.target.value)
        }}
        onBlur={commit}
        onKeyDown={(event) => {
          if (event.key === "Enter") commit()
          else if (event.key === "ArrowUp" || event.key === "ArrowDown") {
            event.preventDefault()
            step(event.key === "ArrowUp" ? 1 : -1)
          }
        }}
        aria-invalid={errorId !== undefined || undefined}
        aria-describedby={errorId}
      />
    </Field>
  )
}

function HorizonRow({
  label,
  surface,
}: {
  label: string
  surface: { code: string; name: string; color: string }
}) {
  return (
    <div data-slot="horizon-row" className="flex flex-col gap-1.5">
      <span className="text-xs text-muted-foreground">{label}</span>
      <div className="flex items-center gap-2 rounded-md bg-muted px-2.5 py-2 text-sm">
        <ColorSwatch
          color={surface.color}
          size="sm"
          shape="square"
          aria-label={`${surface.name} colour`}
        />
        <span className="font-mono text-xs text-muted-foreground">
          {surface.code}
        </span>
        <span className="min-w-0 flex-1 truncate">{surface.name}</span>
        <span className="font-mono text-xs text-muted-foreground uppercase">
          {surface.color.replace("#", "")}
        </span>
      </div>
    </div>
  )
}

function LabelledSlider({
  label,
  value,
  unit,
  min,
  max,
  step = 1,
  onValueChange,
}: {
  label: string
  value: number
  unit?: string
  min: number
  max: number
  step?: number
  onValueChange: (value: number) => void
}) {
  const labelId = React.useId()
  return (
    <div data-slot="labelled-slider" className="flex flex-col gap-2">
      <div className="flex items-center justify-between text-xs">
        <span id={labelId} className="text-muted-foreground">
          {label}
        </span>
        <span className="font-mono tabular-nums">
          {value}
          {unit && <span className="text-muted-foreground">{unit}</span>}
        </span>
      </div>
      <Slider
        aria-labelledby={labelId}
        value={[value]}
        min={min}
        max={max}
        step={step}
        onValueChange={(next) => {
          const [first] = Array.isArray(next) ? next : [next]
          if (first !== undefined) onValueChange(first)
        }}
      />
    </div>
  )
}

export { HorizonForm, HorizonRow, DepthField, LabelledSlider }
export type { HorizonFormProps }

import * as React from "react"
import { cn } from "cn"

type ReadoutRow = {
  label: string
  value: React.ReactNode
  unit?: string
}

function HorizonReadout({
  className,
  rows,
  ...props
}: React.ComponentProps<"dl"> & { rows: ReadoutRow[] }) {
  return (
    <dl
      data-slot="horizon-readout"
      className={cn("flex flex-col gap-1.5 text-xs", className)}
      {...props}
    >
      {rows.map((row) => (
        <div
          key={row.label}
          className="flex items-baseline justify-between gap-3"
        >
          <dt className="text-muted-foreground">{row.label}</dt>
          <dd className="font-mono tabular-nums">
            {row.value}
            {row.unit && (
              <span className="text-muted-foreground">{row.unit}</span>
            )}
          </dd>
        </div>
      ))}
    </dl>
  )
}

export { HorizonReadout }
export type { ReadoutRow }

export type Surface = {
  id: string
  /** Interpreter code, e.g. "K70". */
  code: string
  name: string
  /** Hex colour of the interpreted surface (from the project's colour table). */
  color: string
  /** Mean depth (TVDSS, metres). */
  depth: number
}

export type SurfacePair = {
  id: string
  label: string
  top: string
  base: string
}

export type HorizonSettings = {
  pairId: string
  volumeId: string
  topDepth: number
  bottomDepth: number
  lineWidth: number
  opacity: number
  smoothing: number
}

export const surfaces: [Surface, ...Surface[]] = [
  {
    id: "k70",
    code: "K70",
    name: "Spekk FM Top",
    color: "#218585",
    depth: 2525,
  },
  { id: "l70", code: "L70", name: "Are FM Top", color: "#2D7856", depth: 2639 },
  {
    id: "j80",
    code: "J80",
    name: "Melke FM Top",
    color: "#84A138",
    depth: 2481,
  },
  {
    id: "m10",
    code: "M10",
    name: "Garn FM Top",
    color: "#CB8553",
    depth: 2712,
  },
  { id: "m40", code: "M40", name: "Ile FM Top", color: "#8CA7DE", depth: 2790 },
  {
    id: "n20",
    code: "N20",
    name: "Tofte FM Top",
    color: "#C2867A",
    depth: 2874,
  },
]

export const surfacePairs: [SurfacePair, ...SurfacePair[]] = [
  {
    id: "spekk-are",
    label: "Spekk FM Top → Are FM Top",
    top: "k70",
    base: "l70",
  },
  {
    id: "melke-spekk",
    label: "Melke FM Top → Spekk FM Top",
    top: "j80",
    base: "k70",
  },
  {
    id: "garn-ile",
    label: "Garn FM Top → Ile FM Top",
    top: "m10",
    base: "m40",
  },
  {
    id: "ile-tofte",
    label: "Ile FM Top → Tofte FM Top",
    top: "m40",
    base: "n20",
  },
]

export const volumes = [
  { id: "survey-2", label: "Survey 2" },
  { id: "survey-1", label: "Survey 1 (legacy)" },
  { id: "merged", label: "Merged PSDM" },
]

export const lineWidths = [1, 2, 3, 4, 6, 8]

export const defaultHorizonSettings: HorizonSettings = {
  pairId: "spekk-are",
  volumeId: "survey-2",
  topDepth: 2525,
  bottomDepth: 2639,
  lineWidth: 4,
  opacity: 85,
  smoothing: 20,
}

export function getSurface(id: string): Surface {
  return surfaces.find((surface) => surface.id === id) ?? surfaces[0]
}

export function getPair(id: string): SurfacePair {
  return surfacePairs.find((pair) => pair.id === id) ?? surfacePairs[0]
}

/** The depth pair is valid when the bottom lies deeper than the top. */
export function validateDepths(value: HorizonSettings): string | undefined {
  if (value.bottomDepth <= value.topDepth)
    return "Bottom depth must be deeper than the top depth."
  return undefined
}

"use client"

import * as React from "react"
import { cn } from "cn"
import { PanelRightIcon, PanelRightOpenIcon } from "lucide-react"

import { Badge } from "@tecton/react/components/badge"
import { Button } from "@tecton/react/components/button"
import {
  Panel,
  PanelActions,
  PanelContent,
  PanelFooter,
  PanelHeader,
  PanelTitle,
} from "@tecton/react/tecton/panel"
import { useLocale } from "@tecton/react/tecton/provider"

import { HorizonForm } from "./components/horizon-form"
import { HorizonReadout } from "./components/horizon-readout"
import {
  defaultHorizonSettings,
  getPair,
  validateDepths,
  volumes,
} from "./data"
import type { HorizonSettings } from "./data"

type HorizonsPanelProps = Omit<
  React.ComponentProps<typeof Panel>,
  "children"
> & {
  initialSettings?: HorizonSettings
  onApply?: (value: HorizonSettings) => void
  onCollapse?: () => void
}

/**
 * "2 Horizons" tool panel — surface-pair picker, depth text fields,
 * opacity / smoothing sliders, colour tags and an Apply footer.
 */
function HorizonsPanel({
  className,
  initialSettings = defaultHorizonSettings,
  onApply,
  onCollapse,
  ...props
}: HorizonsPanelProps) {
  const [value, setValue] = React.useState<HorizonSettings>(initialSettings)
  const [applied, setApplied] = React.useState<HorizonSettings>(initialSettings)
  const dirty = JSON.stringify(value) !== JSON.stringify(applied)
  const invalid = validateDepths(value) !== undefined
  const { locale } = useLocale()
  const metres = (depth: number) => depth.toLocaleString(locale)
  const pair = getPair(value.pairId)
  const volume = volumes.find((item) => item.id === value.volumeId)

  return (
    <Panel
      data-slot="horizons-panel"
      className={cn("h-full", className)}
      {...props}
    >
      <PanelHeader>
        <PanelTitle>2 Horizons</PanelTitle>
        <Badge variant="secondary" appearance="outline">
          {pair.label.split(" → ").length} surfaces
        </Badge>
        <PanelActions>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Collapse panel"
            {...(onCollapse === undefined ? {} : { onClick: onCollapse })}
          >
            <PanelRightIcon />
          </Button>
        </PanelActions>
      </PanelHeader>
      <PanelContent className="flex flex-col gap-4">
        <HorizonForm value={value} onChange={setValue} />
        <HorizonReadout
          className="rounded-md bg-surface-alt/60 px-3 py-2"
          rows={[
            { label: "Volume", value: volume?.label ?? "—" },
            {
              label: "Top depth (TVDSS)",
              value: metres(value.topDepth),
              unit: "m",
            },
            {
              label: "Bottom depth (TVDSS)",
              value: metres(value.bottomDepth),
              unit: "m",
            },
            {
              label: "Thickness",
              value: metres(Math.max(0, value.bottomDepth - value.topDepth)),
              unit: "m",
            },
          ]}
        />
      </PanelContent>
      <PanelFooter className="justify-end">
        <Button
          variant="ghost"
          size="sm"
          disabled={!dirty}
          onClick={() => setValue(applied)}
        >
          Reset
        </Button>
        <Button
          size="sm"
          disabled={!dirty || invalid}
          onClick={() => {
            setApplied(value)
            onApply?.(value)
          }}
        >
          Apply
        </Button>
      </PanelFooter>
    </Panel>
  )
}

/** Route-ready page: the panel centred on the canvas. */
export default function HorizonsPanelPage() {
  const [open, setOpen] = React.useState(true)

  return (
    <div
      data-slot="horizons-panel-page"
      className="flex min-h-svh w-full items-start justify-center bg-background px-4 py-8 text-foreground md:items-center"
    >
      {open ? (
        <HorizonsPanel
          className="w-full max-w-sm"
          onCollapse={() => setOpen(false)}
        />
      ) : (
        <Button variant="outline" size="sm" onClick={() => setOpen(true)}>
          <PanelRightOpenIcon data-icon="inline-start" /> Show horizons
        </Button>
      )}
    </div>
  )
}

export { HorizonsPanel, HorizonForm, HorizonReadout }
export {
  surfaces,
  surfacePairs,
  volumes,
  defaultHorizonSettings,
  validateDepths,
} from "./data"
export type { HorizonsPanelProps }
export type { Surface, SurfacePair, HorizonSettings } from "./data"
